	VisitDialogBinding binding;

	public View onCreateView(...){
		View dialogView = inflater.inflate(R.layout.visit_dialog, null);

		binding = VisitDialogBinding.inflate(getLayoutInflater());

		// To access any view in this fragment class, we can just call
		binding.stationNameInput or binding.deleteButton
	}
}
